        valid = True
        for dx, dy in directions:
            nx, ny = x - dx, y - dy
            if nx < 0 or nx >= n or ny < 0 or ny >= n or board[nx][ny] == '#' or used[nx][ny]:
                valid = False
                break
        if valid and all(used[i][j] == False for i in range(x - 1, x + 1) for j in range(y - 1, y + 1)):
