def can_tile_board(n, board):
    # Check if the number of free cells is divisible by 5
    free_cells = sum(row.count('.') for row in board)
    if free_cells % 5 != 0:
        return "NO"

    # Try to place a piece in each possible position
    def place_piece(board, i, j):
        directions = [(0, 0), (-1, 0), (1, 0), (0, -1), (0, 1)]
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < n and 0 <= nj < n and board[ni][nj] == '.':
                board[i][j] = '#'
                board[ni][nj] = '#'
                for ddx, ddy in directions:
                    x, y = ni + ddx, nj + ddy
                    if 0 <= x < n and 0 <= y < n and board[x][y] == '.':
                        board[x][y] = '#'
                return True
        return False

    def unplace_piece(board, i, j):
        directions = [(0, 0), (-1, 0), (1, 0), (0, -1), (0, 1)]
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < n and 0 <= nj < n and board[ni][nj] == '#':
                board[ni][nj] = '.'
        for ddx, ddy in directions:
            x, y = ni + ddx, nj + ddy
            if 0 <= x < n and 0 <= y < n and board[x][y] == '#':
                board[x][y] = '.'

    def backtrack(board, placed):
        if placed == free_cells // 5:
            return True
        for i in range(n):
            for j in range(n):
                if board[i][j] == '.':
                    if place_piece(board, i, j):
                        if backtrack(board, placed + 1):
                            return True
                        unplace_piece(board, i, j)
        return False

    return "YES" if backtrack(board, 0) else "NO"

